namespace NotificationsApp.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private int _nextId = 1;
    private readonly List<Notification> _notifications = new();
    private readonly Lock _lock = new();

    public NotificationService()
    {
        // Seed with initial fake data.
        _notifications.AddRange(new[]
        {
            CreateNotification("Welcome to the notification center!"),
            CreateNotification("Your profile was updated successfully."),
            CreateNotification("New comment on your post."),
        });
    }

    /// <summary>Returns all notifications available at the time of the call.</summary>
    public List<Notification> GetAll()
    {
        lock (_lock)
        {
            return _notifications.ToList();
        }
    }

    /// <summary>Returns only notifications with an Id greater than <paramref name="sinceId"/>.</summary>
    public List<Notification> GetSince(int sinceId)
    {
        lock (_lock)
        {
            return _notifications.Where(n => n.Id > sinceId).ToList();
        }
    }

    /// <summary>
    /// Simulates an external system pushing a new notification every ~8-12 seconds.
    /// Called from a hosted service so the polling page always has something new to find.
    /// </summary>
    internal Notification AddRandom()
    {
        string[] templates =
        [
            "Deployment to production completed.",
            "Disk usage alert: 85 % on /dev/sda1.",
            "Pull request #42 was merged.",
            "Scheduled backup finished successfully.",
            "New user signed up: user_{0}.",
            "Service health-check recovered.",
            "License expires in 7 days.",
        ];

        var msg = string.Format(
            templates[Random.Shared.Next(templates.Length)],
            Random.Shared.Next(1000, 9999));

        lock (_lock)
        {
            var n = CreateNotification(msg);
            _notifications.Add(n);
            return n;
        }
    }

    private Notification CreateNotification(string message)
        => new(Interlocked.Increment(ref _nextId), message, DateTime.UtcNow);
}

namespace NotificationsApp.Services;

/// <summary>
/// Background hosted service that periodically adds fake notifications so
/// the polling loop on the page has something to discover.
/// </summary>
public class NotificationGeneratorService(NotificationService notifications) : BackgroundService
{
    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        while (!stoppingToken.IsCancellationRequested)
        {
            await Task.Delay(TimeSpan.FromSeconds(Random.Shared.Next(8, 13)), stoppingToken);
            notifications.AddRandom();
        }
    }
}

@page "/notifications"
@rendermode InteractiveServer
@using NotificationsApp.Services
@inject NotificationService NotificationSvc
@inject PersistentComponentState PersistState
@implements IDisposable

<PageTitle>Notifications</PageTitle>

<h1>
    Notifications
    <span class="badge bg-primary rounded-pill ms-2">@_notifications.Count</span>
</h1>

@if (_notifications.Count == 0)
{
    <p><em>No notifications yet.</em></p>
}
else
{
    <ul class="list-group mt-3">
        @foreach (var n in _notifications.OrderByDescending(x => x.Id))
        {
            <li class="list-group-item d-flex justify-content-between align-items-start">
                <div>@n.Message</div>
                <small class="text-muted ms-3 text-nowrap">@n.Timestamp.ToString("HH:mm:ss")</small>
            </li>
        }
    </ul>
}

@code {
    private List<Notification> _notifications = new();
    private CancellationTokenSource? _cts;
    private PersistingComponentStateSubscription _persistSub;

    protected override void OnInitialized()
    {
        // During SSR this fetches from the service and persists the data.
        // During interactive re-activation it restores the persisted snapshot
        // instead of hitting the service again.
        _persistSub = PersistState.RegisterOnPersisting(PersistNotifications);

        if (!PersistState.TryTakeFromJson<List<Notification>>("notifications", out var restored))
        {
            _notifications = NotificationSvc.GetAll();
        }
        else
        {
            _notifications = restored!;
        }
    }

    private Task PersistNotifications()
    {
        PersistState.PersistAsJson("notifications", _notifications);
        return Task.CompletedTask;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        // OnAfterRender never runs during static SSR — only once the page is
        // interactive in the browser, so the polling loop starts only then.
        if (!firstRender)
            return;

        _cts = new CancellationTokenSource();
        var token = _cts.Token;

        _ = Task.Run(async () =>
        {
            while (!token.IsCancellationRequested)
            {
                await Task.Delay(TimeSpan.FromSeconds(5), token);

                var maxId = _notifications.Count > 0
                    ? _notifications.Max(n => n.Id)
                    : 0;

                var newer = NotificationSvc.GetSince(maxId);
                if (newer.Count > 0)
                {
                    _notifications.AddRange(newer);
                    await InvokeAsync(StateHasChanged);
                }
            }
        }, token);
    }

    public void Dispose()
    {
        _persistSub.Dispose();
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

